// eslint-disable-next-line @typescript-eslint/no-namespace
namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadneUctovaniTab extends GContentBase {

        private gridUctovaniStep1: JQuery<HTMLElement>;
        private gridUctovaniStep2: JQuery<HTMLElement>;
        private gridUctovaniStep3: JQuery<HTMLElement>;
        pokDoklady: Gordic.Hpl.Interface.GPokDokladDto[];

        onContentReady() {

            var that = this;


            this.title = "Hromadné účtování";
            this.setBreadcrumbs([{ caption: this.title, defaultAction: true }]);

            var gf = new Gordic.Data.GridFormat();
            gf.addTextColumn({
                name: "ixp",
                caption: "jres:31302005", //RC 31302005 : PID
                sortable: false
            })

            const gridActionDetail = new GAction($.extend(true, Gordic.Eko.Action.actionDetail({
                run: function (ev, ctx) {
                    that.navigate("Gordic.Pok.WebClient.GPokDetailDokladuTab", {
                        ixp: ctx.cellInfo.data.ixp,
                        newPodani: false,
                        Id: "GPokDetailDokladu#"
                    });
                },
                enabled: true
            }), { name: "actDetail" }))



            this.navigate<Gordic.Eko.Components.TwoStepsOptions<Gordic.Hpl.Interface.GPokDokladDto>>(Gordic.Eko.Components.TwoStepsContent, {
                title: "Hromadné účtování pokladních dokladů",
                gridFormat: gf,
                keys: "ixp",
                data: this.pokDoklady,
                indicatorType: "KPI",                
                firstStep: {
                    title: "Hromadné účtování pokladích dokladů",
                    description: "Kontrola před hromadným zaúčtováním",                 
                    gridTabTitle: "Vybrané pokladní doklady",
                    defaultAction: gridActionDetail,
                    checkAction: (model, data) => {

                        var view = new Gordic.Data.View(data, { key: "ixp" });
                        var ixpArray = data.map(function (d) { return d.ixp; });
                        let i = 0;

                        let def = $.Deferred();

                        ixpArray.forEach(function (x) {

                            that.isl.PokDoklad.seznamPermissions(rq => { return { ixp: x } }).get()
                                .done(function (data) {

                                    view.getDataRows(true).forEach(function (meta) {

                                        if (meta.data.ixp === x) {
                                            i = i + 1;
                                            meta.data.wiz_kind = data.LzeZauctovat.value ? Gordic.Isl.GOperationResultKind.Success : Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = data.LzeZauctovat.message;
                                            meta.data.wiz_check = data.LzeZauctovat.value;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });

                                })
                                .fail(function (xhr, type, vobj) {

                                    view.getDataRows(true).forEach(function (meta) {
                                        vobj.handled = true;
                                        if (meta.data.ixp === x) {
                                            i = i + 1;
                                            meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = vobj.baseMessage;
                                            meta.data.wiz_check = false;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });


                                });
                        })
                        return def.promise();

                    },                    
                    nextActionName: "Zaúčtovat",
                    nextAction: (model, data) => {

                        let def = $.Deferred();
                        let y = 0;

                        if (data.length == 0)
                            def.resolve(data);


                        data.forEach(function (row) {
                            that.isl.PokDoklad.porovnatRezZapSAktkZpz(rq => {
                                return {
                                    ixp: row.ixp
                                }
                            })
                                .get()
                                .done(function () {
                                    that.isl.PokDoklad.zauctovat(
                                        rq => {
                                            return {
                                                ixp: row.ixp,
                                                kontrolaPol: true
                                            }
                                        })
                                        .get()
                                        .done(function () {
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Success;
                                            row.wiz_txt_err = "Doklad byl úspěšně zaúčtován!";
                                        })
                                        .fail(function (xhr, type, vobj) {
                                            if (type === "exception") {
                                                if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                                    vobj.handled = true;
                                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                    row.wiz_txt_err = vobj.baseMessage;

                                                }
                                                else if (vobj.data.member == "kontrolaPol") {
                                                    vobj.handled = true;
                                                    //row.stavU = 2;
                                                    //row.vysledekU = vobj.baseMessage;
                                                    //question stav??
                                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                    row.wiz_txt_err = vobj.baseMessage;
                                                }
                                                else {
                                                    vobj.handled = true;
                                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                    row.wiz_txt_err = vobj.baseMessage;

                                                }
                                            }
                                        })
                                        .always(function () {
                                            y = y + 1;

                                            if (y == data.length) {
                                                def.resolve(data)
                                            }
                                        });
                                })
                                .fail(function (xhr, type, vobj) {
                                    if (type === "exception") {
                                        if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                            vobj.handled = true;
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            row.wiz_txt_err = vobj.baseMessage;


                                        }
                                        else if (vobj.baseType === "Gordic.General.GDataInvalidException") {
                                            vobj.handled = true;
                                            //row.stavU = 2;
                                            //row.vysledekU = vobj.baseMessage;
                                            //question
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            row.wiz_txt_err = vobj.baseMessage;
                                        }
                                    }
                                })
                                .always(function () {
                                    if (y == data.length) {
                                        def.resolve(data)
                                    }
                                });
                        });
                        return def.promise();
                    },
                },

                lastStep:
                {
                    title: "Výsledek",
                    gridTabTitle: "Zaúčtované pokladní doklady",
                    description: "Výsledek hromadného zaúčtování"
                },
                completeDelegate: (view) => {

                    that.close(true);
                },
                cancelDelegate: () => {
                    that.close(false);
                },
            }, { title: "Hromadné účtování pokladních dokladů" });

        }


    }


}


